const resolveContentReport = `-- name: ResolveContentReport :one
UPDATE compliance.content_report
SET status = $3,
    outcome_note = $4,
    reviewed_by_employee_id = $5,
    reviewed_at = $6
WHERE organization_id = $1
  AND id = $2
  AND status = 'outstanding'
RETURNING id, organization_id, reporter_employee_id, reported_employee_id, target_kind, target_id, content_snapshot, reason, note, status, outcome_note, reviewed_by_employee_id, reviewed_at, created_at
`

type ResolveContentReportParams struct {
	OrganizationID       dbuuid.UUID        `json:"organization_id"`
	ID                   dbuuid.UUID        `json:"id"`
	Status               string             `json:"status"`
	OutcomeNote          pgtype.Text        `json:"outcome_note"`
	ReviewedByEmployeeID dbuuid.NullUUID    `json:"reviewed_by_employee_id"`
	ReviewedAt           pgtype.Timestamptz `json:"reviewed_at"`
}

// Records an outcome. The status predicate makes re-resolution a no-op at the SQL
// layer as well as the logic layer: an already-resolved report returns no row.
func (q *Queries) ResolveContentReport(ctx context.Context, db DBTX, arg *ResolveContentReportParams) (*ComplianceContentReport, error) {
	row := db.QueryRow(ctx, resolveContentReport,
		arg.OrganizationID,
		arg.ID,
		arg.Status,
		arg.OutcomeNote,
		arg.ReviewedByEmployeeID,
		arg.ReviewedAt,
	)
	var i ComplianceContentReport
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ReporterEmployeeID,
		&i.ReportedEmployeeID,
		&i.TargetKind,
		&i.TargetID,
		&i.ContentSnapshot,
		&i.Reason,
		&i.Note,
		&i.Status,
		&i.OutcomeNote,
		&i.ReviewedByEmployeeID,
		&i.ReviewedAt,
		&i.CreatedAt,
	)
	return &i, err
}

const resolveOutstandingRemovalRequestsForEmployee = `-- name: ResolveOutstandingRemovalRequestsForEmployee :exec
UPDATE compliance.removal_request
SET status = 'granted',
    decided_by_employee_id = $4,
    decided_at = $3
WHERE organization_id = $1
  AND employee_id = $2
  AND status = 'outstanding'
`

type ResolveOutstandingRemovalRequestsForEmployeeParams struct {
	OrganizationID      dbuuid.UUID        `json:"organization_id"`
	EmployeeID          dbuuid.UUID        `json:"employee_id"`
	DecidedAt           pgtype.Timestamptz `json:"decided_at"`
	DecidedByEmployeeID dbuuid.NullUUID    `json:"decided_by_employee_id"`
}

// An administrator offboarding a worker the ordinary way resolves any outstanding
// request as a side effect, so it does not linger in the owner queue.
func (q *Queries) ResolveOutstandingRemovalRequestsForEmployee(ctx context.Context, db DBTX, arg *ResolveOutstandingRemovalRequestsForEmployeeParams) error {
	_, err := db.Exec(ctx, resolveOutstandingRemovalRequestsForEmployee,
		arg.OrganizationID,
		arg.EmployeeID,
		arg.DecidedAt,
		arg.DecidedByEmployeeID,
	)
	return err
}
